from pathlib import Path
from html import escape
from PIL import Image
from data import TABLES
import json, re
ROOT=Path(__file__).resolve().parent.parent
SITE=ROOT/'site'
imgs={'hero':'dbl_row_ball_bearing_idler_.png','single':'v-belt_idler_pulleys.png','double':'double-row-idler-pulley_cut.png','drive':'vbelt_drive_pulley_img1.png','v-single':'srb_diagram.png','flat-single':'srb_diagram2.png','v-double':'v-idler_drb_img1.png','flat-faced':'flatfaced_idler_drb_img1.png','flat-flanged':'flatflanged_idler_drb_img1.png','a':'a-grove_drive_pulley.png','b':'b-grove_drive_pulley.png','c':'c-grove_drive_pulley.png','special':'special-grove_drive_pulley.png'}
for name,source in imgs.items():
 if name not in ('hero', 'single', 'drive'):
  # Line drawings: color-to-alpha against white so fine dimension lines survive on any page color.
  import numpy as np
  a=np.asarray(Image.open(ROOT/'reference/img/images'/source).convert('RGBA')).astype(float)
  d=255-a[...,:3]; d=np.where(d<=6,0,(d-6)*255/249); al=d.max(2)/255
  col=np.clip(np.where(al[...,None]>0,255-d/np.maximum(al,1e-6)[...,None],0),0,255)
  Image.fromarray(np.dstack([col,al*a[...,3]]).round().astype('uint8'),'RGBA').save(SITE/'assets/img'/f'{name}-transparent.png',optimize=True)
def image(name,alt, eager=False):
 filename=f'{name}-transparent.png'
 im=Image.open(SITE/'assets/img'/filename); w,h=im.size
 return f'<img src="/assets/img/{filename}" alt="{escape(alt)}" width="{w}" height="{h}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def table(key, label=None):
 rows=TABLES[key]
 def clean(s): return escape(' '.join(s.split()))
 head=''.join('<th scope="col">'+clean(x or 'Part No.')+'</th>' for x in rows[0])
 body=''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+clean(c)+('</th>' if i==0 else '</td>') for i,c in enumerate(row))+'</tr>' for row in rows[1:])
 return f'<div class="table-scroller"><div class="table-wrap" tabindex="0" role="region" aria-label="{escape(label or key.replace('_', ' ') + ' dimensions')}"><table><caption class="visually-hidden">{escape(label or key.replace("_", " ") + " dimensions")}</caption><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div></div>'
def section(id,title,key,img):
 return f'<section class="product-section" id="{id}"><div class="section-heading"><h2>{title}</h2></div><div class="product-layout"><figure class="diagram"><a href="/assets/img/{img}-transparent.png">{image(img,title+" diagram")}</a></figure>{table(key,title + " dimensions")}</div></section>'
nav=[('/','Home'),('/idler-pulleys/single-row/','Single Row'),('/idler-pulleys/double-row/','Double Row'),('/drive-pulleys/','Drive Pulleys'),('/bearings/','Bearings'),('/contact/','Contact')]
def layout(title,desc,path,content):
 links=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==path else '')+f'>{n}</a>' for u,n in nav)
 org={'@context':'https://schema.org','@type':'Organization','name':'Don Dye Company, Inc.','url':'https://dondyeco.com/','telephone':'(620) 532-3131','faxNumber':'(620) 532-2141','email':'info@dondyeco.com','address':{'@type':'PostalAddress','postOfficeBoxNumber':'107','addressLocality':'Kingman','addressRegion':'KS','postalCode':'67068'}}
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>{escape(title)} | Don Dye Company</title><meta name="description" content="{escape(desc)}"><meta property="og:title" content="{escape(title)} | Don Dye Company"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="https://dondyeco.com{path}"><link rel="icon" href="/assets/img/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/bricolage-700.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/css/site.css"><script type="application/ld+json">{json.dumps(org)}</script><script src="/assets/js/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="shell header-inner"><a class="brand" href="/" aria-label="Don Dye Company home"><svg viewBox="0 0 180 76" role="img" aria-label="Don Dye"><ellipse cx="90" cy="38" rx="86" ry="34" fill="#108a3f"/><text x="90" y="47" text-anchor="middle" fill="white" font-family="Arial, sans-serif" font-size="35" font-weight="bold" font-style="italic">don dye</text></svg></a><button class="menu" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{links}</nav><a class="header-phone" href="tel:+16205323131">(620) 532-3131</a></div></header><main id="main">{content}</main><footer><div class="shell footer-grid"><div><a class="footer-brand" href="/">DON DYE COMPANY, INC.</a><p>P.O. Box 107<br>Kingman, KS 67068</p></div><div><a href="tel:+16205323131">(620) 532-3131</a><br>Fax (620) 532-2141<br><a href="mailto:info@dondyeco.com">info@dondyeco.com</a></div><div><a href="/assets/docs/catalog.pdf">Catalog (PDF, 4.6 MB)</a><br><a href="/contact/">Contact</a></div></div></footer></body></html>'''
def intro(title,text,links=''):
 trail = '<span>Idler Pulleys</span><span aria-hidden="true">/</span>' if title in ('Single Row Idler Pulleys', 'Double Row Idler Pulleys') else ''
 current = title.replace(' Idler Pulleys', '') if trail else title
 return f'<div class="page-head"><div class="shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>{trail}<span aria-current="page">{escape(current)}</span></nav><h1>{title}</h1>{links}</div></div>'
def write(path,title,desc,content):
 dest=SITE/path.strip('/')/'index.html' if path!='/' else SITE/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(layout(title,desc,path,content))
cta='<a class="button" href="/contact/">Request a quote</a>'
pdf='<a class="text-link" href="/assets/docs/catalog.pdf">Download catalog</a>'
cards=[('01','Single Row Idler Pulleys','/idler-pulleys/single-row/','single','V-belt idler pulleys'),('02','Double Row Idler Pulleys','/idler-pulleys/double-row/','hero','Double row ball bearing idler pulley'),('03','Industrial Drive Pulleys','/drive-pulleys/','drive','Drive pulley diagram'),('04','Unground Ball Bearings','/bearings/',None,'')]
cardhtml=''.join(f'<a class="card{" card-text" if not img else ""}" href="{url}">' + (f'<div class="card-image">{image(img,alt)}</div>' if img else '') + f'<h3>{name}</h3></a>' for num,name,url,img,alt in cards)
home=f'''<section class="hero"><div class="shell hero-grid"><div><h1>V-Belt &amp; Flat Idler Drive Pulleys</h1><div class="actions">{cta}{pdf}</div></div><div class="hero-image">{image('hero','Double row ball bearing idler pulley',True)}</div></div></section><section class="shell section"><div class="section-heading"><h2>Products</h2></div><div class="cards">{cardhtml}</div></section><section class="features"><div class="shell feature-grid"><div><h2>Construction</h2><p>Don Dye pressed steel pulleys for agriculture, industry and home are designed as a complete, self-contained unit for either the flat or V side of a belt.</p></div><ul><li>Riveted for strength and durability; no spot welding</li><li>Smoothly rolled edges help eliminate belt chafing and scuffing</li><li>Weep holes allow water drainage when mounted horizontally</li><li>Zinc plated</li><li>Compression ring · USA Patent No. 4518372</li></ul></div></section>'''
write('/','Pressed Steel Pulleys and Bearings','V-Belt & Flat Idler Drive Pulleys for Agriculture, Industry and Home.',home)
single='''<p>Don Dye pressed steel pulleys are designed to make a complete, economical, self-contained unit for either the flat or V side of a belt. They are furnished with a single-row, radial-type precision ground, pre-lubricated ball bearing made of 52100 bearing steel, with contact-type seals to retain lubricant and protect against dirt, dust or foreign matter.</p><p>These bearings contain a 60% fill of high temperature grease; no re-lubrication is required. The inner ring is extended on both sides to provide clearance for abutting parts and greater support on the shaft. A compression ring (USA Patent No. 4518372) between the bearing and pulley bearing pocket provides a firm fit and helps distribute loads evenly to the outer bearing race.</p><p>Accurately bore sized for mounting on standard 1/2" or 5/8" bolts. A 1/2" bore removable sleeve is standard in all pulleys; a 3/8" sleeve is available on request.</p>'''
write('/idler-pulleys/single-row/','Single Row Idler Pulleys','Single-row bearing V-idler and flat idler pulleys.',intro('Single Row Idler Pulleys','Pressed steel pulleys for the flat or V side of a belt.','<div class="jump"><a href="#v-idler">V-Idler</a><a href="#flat-idler">Flat Idler</a></div>')+f'<div class="shell content">'+section('v-idler','V-Idler Single Row Bearing','v-idler_srb','v-single')+section('flat-idler','Flat Idler Single Row Bearing','flat-iderl_srb','flat-single')+f'<div class="prose product-details">{single}</div>{cta}</div>')
double='''<p>This line of heavy duty double row ball bearing flat, flanged, and V-groove idlers was developed to handle heavier loads that exceed the capacity of single row ball bearing idlers. The double row idlers are more stable when side loads or off-center loads occur.</p><p>Available with 3/8", 1/2", 5/8" and 3/4" bolt mounting, these riveted idlers are constructed from 13 gauge material. Precision bearings made of 52100 bearing steel are pre-lubricated with high temperature lubricant and have contact-type seals. No re-lubrication is required. A compression ring (USA patent 4518372) provides a firm fit and helps distribute loads to the outer bearing race.</p>'''
write('/idler-pulleys/double-row/','Double Row Idler Pulleys','Heavy duty double row ball bearing flat, flanged and V-groove idlers.',intro('Double Row Idler Pulleys','Heavy duty flat, flanged and V-groove idlers.','<div class="jump"><a href="#v-idler">V-Idler</a><a href="#flat-faced">Flat Faced</a><a href="#flat-flanged">Flat Flanged</a></div>')+f'<div class="shell content">'+section('v-idler','V-Idler Double Row Bearing','v-idler_drb','v-double')+section('flat-faced','Flat Faced Idler Double Row','flat_faced_idler_drb','flat-faced')+section('flat-flanged','Flat Flanged Idler Double Row','flat_flanged_idler_drb','flat-flanged')+f'<div class="prose product-details">{double}</div>{cta}</div>')
drive='''<p>The pulleys are formed on compound dies designed and built in our plant. The halves are riveted together and the hubs welded in by MIG welders on turning and holding fixtures designed and built in our plant. They require no balancing and are easily adapted to standard or special uses.</p><h2>Standard hubs</h2><p>The standard sheave is 14 gauge and has the same part number regardless of hub design. Standard hubs have a keyway and two set screw holes tapped with N.C. threads. Please order pulley number with hub number.</p>'''+table('idp', 'Standard hubs dimensions')+'''<p>Other hubs are available, including special bore sizes, splines and tapers.</p><h2>Specials</h2><p>Specials are produced in 14 gauge, 13 gauge and 11 gauge with combinations of hub lengths and bores to 1 1/2" diameter. Hubs are machined from 2", 2 1/8" and 2 1/2" diameter steel bar stock. Bores can be tapered with keyways, tapered keyways, broached splines, hex bores, metric bores or dimensions, pin holes or other special shapes and combinations. Pulleys can be trimmed and mounted on the same hub for step cone effect or speed change, also with double row ball bearing hubs.</p><p>Most of these pulleys are available with a 6 1/2" diameter flat area in the center for punching a bolt hole arrangement to bolt on a customer's hub.</p>'''
write('/drive-pulleys/','Industrial Drive Pulleys','Pressed steel drive pulleys built to order for OEMs.',intro('Industrial Drive Pulleys','Built to order for OEMs, with minimum volumes per part number.','<div class="jump"><a href="#a-groove">A Groove</a><a href="#b-groove">B Groove</a><a href="#c-groove">C Groove</a><a href="#special-groove">Special Groove</a></div>')+f'<div class="shell content"><div class="prose"><p>Drive pulleys are built to order for OEMs and require minimum volumes per part number.</p>{drive}</div>'+''.join(section(i+'-groove',t+' Groove','idp_'+i+'-grove',i) for i,t in [('a','A'),('b','B'),('c','C'),('special','Special')])+cta+'</div>')
bearing='''<p>These bearings are used in a wide range of applications, including grain augers, farm equipment, wheels, conveyors, lawn mowers and idler pulleys. They have been used at speeds up to and exceeding 2500 RPM in uses such as V-belt tightener pulleys.</p><p>They are made primarily for straight radial service; due to deep ball grooves they are also used for thrust loads. Ball raceways are machine formed to a smooth finish, and outer races are stamped and coined from cold rolled steel, then heat treated. They contain a full complement of balls and are furnished either shielded and grease packed or shielded and grease packed with neoprene seals.</p>'''
write('/bearings/','Unground Ball Bearings','Unground ball bearings for a wide range of applications.',intro('Unground Ball Bearings','For grain augers, farm equipment, wheels, conveyors, lawn mowers and idler pulleys.')+f'<div class="shell content"><div class="prose">{bearing}</div><section class="product-section"><div class="section-heading"><h2>Dimensions</h2></div>{table("ubb", "Unground ball bearings dimensions")}</section>{cta}</div>')
form='''<form id="contact-form"><!-- Replace the mailto fallback with a production form endpoint here. --><div class="form-grid"><label>Name <input name="Name" autocomplete="name" required></label><label>Company <input name="Company" autocomplete="organization"></label><label>Email <input name="Email" type="email" autocomplete="email" required></label><label>Phone <input name="Phone" type="tel" autocomplete="tel"></label><label class="wide">Part numbers / quantities <input name="Part numbers / quantities"></label><label class="wide">Message <textarea name="Message" rows="6" required></textarea></label></div><button class="button" type="submit">Prepare email</button><p id="form-status" role="status"></p></form>'''
write('/contact/','Contact & Quotes','Contact Don Dye Company in Kingman, Kansas for pulley and bearing inquiries.',intro('Contact & Quotes','')+f'<div class="shell contact-layout"><div class="contact-details"><h2>Don Dye Company, Inc.</h2><p>P.O. Box 107<br>Kingman, KS 67068</p><p><a href="tel:+16205323131">(620) 532-3131</a><br>Fax (620) 532-2141<br><a href="mailto:info@dondyeco.com">info@dondyeco.com</a></p></div><div>{form}</div></div>')
