paths={'index.htm':'/','srip.htm':'/idler-pulleys/single-row/','v-idler_srb.htm':'/idler-pulleys/single-row/#v-idler','flat-iderl_srb.htm':'/idler-pulleys/single-row/#flat-idler','drip.htm':'/idler-pulleys/double-row/','v-idler_drb.htm':'/idler-pulleys/double-row/#v-idler','flat_faced_idler_drb.htm':'/idler-pulleys/double-row/#flat-faced','flat_flanged_idler_drb.htm':'/idler-pulleys/double-row/#flat-flanged','idp.htm':'/drive-pulleys/','idp_a-grove.htm':'/drive-pulleys/#a-groove','idp_b-grove.htm':'/drive-pulleys/#b-groove','idp_c-grove.htm':'/drive-pulleys/#c-groove','idp_special-grove.htm':'/drive-pulleys/#special-groove','ubb.htm':'/bearings/','docs/catalog.pdf':'/assets/docs/catalog.pdf'}
